import { GEO } from './toronto-geodata.js';

// js/city-config.js
// Toronto spatial configuration & street database at true 1:1 scale, derived from the real geography in
// js/toronto-geodata.js (generated by tools/build-geodata.mjs from OpenStreetMap).
//
// World frame: 1 unit = 1 m, x = street-grid east, z = grid south (north = -z), origin at the centreline intersection
// of Yonge St & Queen St; the axes are turned -16.7° from true north like the street grid itself (Toronto's "north" up
// Yonge St points north-north-west). Every street sits where it really is: Bloor St at z ≈ -2060, College St at
// z ≈ -1030, Dundas St at z ≈ -440, King St at z ≈ 390, Front St at z ≈ 660, Queens Quay at z ≈ 1240; Bathurst St at
// x ≈ -2060, Spadina Ave at x ≈ -1410, University Ave at x ≈ -590, Bay St at x ≈ -190, Jarvis St at x ≈ 520,
// Parliament St at x ≈ 1260. The detailed downtown runs from just west of Bathurst St to the Don River and from just
// north of Bloor St down to the harbour; the rest of the city, the lake and the Toronto Islands are low-detail
// (surroundings.js).

const toPts = (flat) => {
  const out = [];
  for (let i = 0; i < flat.length; i += 2) out.push({ x: flat[i], z: flat[i + 1] });
  return out;
};
const DETAIL = GEO.frame.detail;

// ---------------------------------------------------------------------------------------------------------------------
// Land: downtown's ground (the detailed city, at the real dock walls along the harbour) and how far any point is from
// its edge
// ---------------------------------------------------------------------------------------------------------------------
const CITY_LAND = toPts(GEO.downtown);
const INNER_SHORE = toPts(GEO.innerShore);
const CITY_BOUNDS = (() => {
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (const p of CITY_LAND) {
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
  }
  return { minX, maxX, minZ, maxZ, sidewalkHeight: 0.22, waterLevel: -2.0 };
})();

// Signed distance to the edge of downtown's land (m; > 0 on land), on a 4 m grid: the dock walls along the harbour and
// the edges of the detailed city inland. `water` is the distance to the lake alone (the inland edges don't count).
const LAND_FIELD = (() => {
  const cell = 4;
  const pad = 80;
  const x0 = CITY_BOUNDS.minX - pad;
  const z0 = CITY_BOUNDS.minZ - pad;
  const nx = Math.ceil((CITY_BOUNDS.maxX - x0 + pad) / cell) + 1;
  const nz = Math.ceil((CITY_BOUNDS.maxZ - z0 + pad) / cell) + 1;
  const inside = new Uint8Array(nx * nz);
  const P = CITY_LAND;
  const xs = [];
  for (let j = 0; j < nz; j++) {
    const z = z0 + (j + 0.5) * cell;
    xs.length = 0;
    for (let i = 0, k = P.length - 1; i < P.length; k = i++) {
      const a = P[k], b = P[i];
      if ((a.z > z) !== (b.z > z)) xs.push(a.x + ((z - a.z) * (b.x - a.x)) / (b.z - a.z));
    }
    xs.sort((p, q) => p - q);
    for (let n = 0; n + 1 < xs.length; n += 2) {
      const i0 = Math.max(0, Math.ceil((xs[n] - x0) / cell - 0.5));
      const i1 = Math.min(nx - 1, Math.floor((xs[n + 1] - x0) / cell - 0.5));
      for (let i = i0; i <= i1; i++) inside[j * nx + i] = 1;
    }
  }
  // Water cells: off the land and not beyond the inland edges of the window (the lake, the slips, the Don)
  const lake = new Uint8Array(nx * nz);
  for (let j = 0; j < nz; j++) {
    for (let i = 0; i < nx; i++) {
      const x = x0 + (i + 0.5) * cell;
      const z = z0 + (j + 0.5) * cell;
      const beyond = x < DETAIL.x0 + 1 || x > DETAIL.x1 - 1 || z < DETAIL.z0 + 1;
      lake[j * nx + i] = !inside[j * nx + i] && !beyond ? 1 : 0;
    }
  }
  const edt = (src) => {
    // squared distance (cells) to the nearest source cell, Felzenszwalb & Huttenlocher
    const INF = 1e20;
    const out = new Float64Array(nx * nz);
    const n = Math.max(nx, nz);
    const f = new Float64Array(n), v = new Int32Array(n), zz = new Float64Array(n + 1);
    const pass = (len, get, set) => {
      for (let q = 0; q < len; q++) f[q] = get(q);
      let k = 0;
      v[0] = 0; zz[0] = -INF; zz[1] = INF;
      for (let q = 1; q < len; q++) {
        let s = ((f[q] + q * q) - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]);
        while (s <= zz[k]) { k--; s = ((f[q] + q * q) - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]); }
        k++; v[k] = q; zz[k] = s; zz[k + 1] = INF;
      }
      k = 0;
      for (let q = 0; q < len; q++) {
        while (zz[k + 1] < q) k++;
        set(q, (q - v[k]) * (q - v[k]) + f[v[k]]);
      }
    };
    for (let i = 0; i < nx * nz; i++) out[i] = src(i) ? 0 : INF;
    for (let i = 0; i < nx; i++) pass(nz, (q) => out[q * nx + i], (q, val) => (out[q * nx + i] = val));
    for (let j = 0; j < nz; j++) pass(nx, (q) => out[j * nx + q], (q, val) => (out[j * nx + q] = val));
    return out;
  };
  const toOff = edt((i) => !inside[i]);
  const toOn = edt((i) => inside[i]);
  const toLake = edt((i) => lake[i]);
  const sd = new Float32Array(nx * nz);
  const water = new Float32Array(nx * nz);
  for (let i = 0; i < nx * nz; i++) {
    sd[i] = inside[i] ? (Math.sqrt(toOff[i]) - 0.5) * cell : -(Math.sqrt(toOn[i]) - 0.5) * cell;
    water[i] = (Math.sqrt(toLake[i]) - 0.5) * cell;
  }
  return { cell, x0, z0, nx, nz, sd, water };
})();
function sampleField(arr, x, z) {
  const F = LAND_FIELD;
  const fx = Math.max(0, Math.min(F.nx - 1.001, (x - F.x0) / F.cell - 0.5));
  const fz = Math.max(0, Math.min(F.nz - 1.001, (z - F.z0) / F.cell - 0.5));
  const i = Math.floor(fx);
  const j = Math.floor(fz);
  const tx = fx - i;
  const tz = fz - j;
  const a = arr[j * F.nx + i] * (1 - tx) + arr[j * F.nx + i + 1] * tx;
  const b = arr[(j + 1) * F.nx + i] * (1 - tx) + arr[(j + 1) * F.nx + i + 1] * tx;
  return a * (1 - tz) + b * tz;
}
/** Signed distance (m) from (x, z) to the edge of downtown's land: positive on land, negative over the water */
const landDistance = (x, z) => sampleField(LAND_FIELD.sd, x, z);
/** Distance (m) from (x, z) to the lake (or a slip, or the Don River); 0 over the water */
const waterDistance = (x, z) => Math.max(0, sampleField(LAND_FIELD.water, x, z));
/** Is (x, z) on downtown's land, at least `margin` m in from its edge? */
const isOnLand = (x, z, margin = 0) => landDistance(x, z) >= margin;
/** (x, z) moved straight in from the edge until it stands `margin` m inside downtown's land (unchanged if it does) */
function pushOntoLand(x, z, margin = 0) {
  let px = x;
  let pz = z;
  for (let it = 0; it < 6; it++) {
    const d = landDistance(px, pz);
    if (d >= margin) break;
    const e = 1.5;
    let gx = landDistance(px + e, pz) - landDistance(px - e, pz);
    let gz = landDistance(px, pz + e) - landDistance(px, pz - e);
    const g = Math.hypot(gx, gz);
    if (g < 1e-6) {
      // deep in the water: head for the middle of the city
      gx = (CITY_BOUNDS.minX + CITY_BOUNDS.maxX) / 2 - px;
      gz = (CITY_BOUNDS.minZ + CITY_BOUNDS.maxZ) / 2 - pz;
    }
    const gl = Math.hypot(gx, gz) || 1;
    const step = margin - d + 0.5;
    px += (gx / gl) * step;
    pz += (gz / gl) * step;
  }
  return { x: px, z: pz };
}

// ---------------------------------------------------------------------------------------------------------------------
// Around downtown: the mainland beyond the detailed city (west to Etobicoke & Mississauga, north up Yonge St, east to
// Scarborough), the Port Lands south of the Keating Channel, the Toronto Islands & Ontario Place's islands
// ---------------------------------------------------------------------------------------------------------------------
const MAINLAND_POLYGONS = Object.fromEntries(Object.entries(GEO.mainland).map(([k, flat]) => [k, toPts(flat)]));
const ISLAND_POLYGONS = GEO.islands.map(toPts); // largest first: Toronto Island (Hanlan's Point to Ward's Island)
/** A real place (longitude, latitude) in the world frame: the frame is an affine image of the local tangent plane
 *  (tools/geo-base.mjs toWorld), so this is exact */
function LL(lon, lat) {
  const [lat0, lon0, kx, ky, theta, ou, ov] = GEO.frame.ll;
  const e = (lon - lon0) * kx;
  const n = (lat - lat0) * ky;
  const c = Math.cos(theta);
  const s = Math.sin(theta);
  return { x: e * c - n * s - ou, z: -(e * s + n * c) - ov };
}
const POINTS = Object.fromEntries(Object.entries(GEO.points).map(([k, [x, z]]) => [k, { x, z }]));

// ---------------------------------------------------------------------------------------------------------------------
// Streets: the real centrelines (OpenStreetMap), merged per street, with Toronto's own abbreviations for the signs
// ---------------------------------------------------------------------------------------------------------------------
const ABBREV = [
  [/\bStreet\b/g, 'St'], [/\bAvenue\b/g, 'Ave'], [/\bBoulevard\b/g, 'Blvd'], [/\bRoad\b/g, 'Rd'], [/\bCrescent\b/g, 'Cres'],
  [/\bDrive\b/g, 'Dr'], [/\bPlace\b/g, 'Pl'], [/\bSquare\b/g, 'Sq'], [/\bCourt\b/g, 'Crt'], [/\bTerrace\b/g, 'Terr'],
  [/\bGardens\b/g, 'Gdns'], [/\bCircle\b/g, 'Circ'], [/\bParkway\b/g, 'Pkwy'], [/\bExpressway\b/g, 'Expy'], [/\bLane\b/g, 'Lane'],
  [/\bEast$/, 'E'], [/\bWest$/, 'W'], [/\bNorth$/, 'N'], [/\bSouth$/, 'S']
];
/** "Queen Street West" -> "Queen St W" (as on Toronto's street-name signs) */
function shortName(name) {
  let s = name || '';
  for (const [re, r] of ABBREV) s = s.replace(re, r);
  return s;
}
// Named roads (the real centreline, merged per street) — maps, labels & lookups
const ROADS = GEO.roads.map(([name, w, dir, lanes, hw, flat]) => ({ name: shortName(name), full: name, w, dir, lanes, highway: !!hw, pts: toPts(flat) }));

// Nearest-road index (labels, sidewalk tests): uniform grid of road segments
const ROAD_CELL = 64;
const ROAD_GRID = new Map();
for (const r of ROADS) {
  for (let i = 0; i + 1 < r.pts.length; i++) {
    const a = r.pts[i];
    const b = r.pts[i + 1];
    const seg = { r, ax: a.x, az: a.z, bx: b.x, bz: b.z };
    const ix0 = Math.floor(Math.min(a.x, b.x) / ROAD_CELL), ix1 = Math.floor(Math.max(a.x, b.x) / ROAD_CELL);
    const iz0 = Math.floor(Math.min(a.z, b.z) / ROAD_CELL), iz1 = Math.floor(Math.max(a.z, b.z) / ROAD_CELL);
    for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
      const k = ix * 100000 + iz;
      if (!ROAD_GRID.has(k)) ROAD_GRID.set(k, []);
      ROAD_GRID.get(k).push(seg);
    }
  }
}
/** Nearest roads to (x, z) within `radius`: [{ road, dist, horizontal }] sorted by distance (one entry per road name) */
function nearestRoads(x, z, radius = 60, withHighways = false) {
  const best = new Map();
  const ix0 = Math.floor((x - radius) / ROAD_CELL), ix1 = Math.floor((x + radius) / ROAD_CELL);
  const iz0 = Math.floor((z - radius) / ROAD_CELL), iz1 = Math.floor((z + radius) / ROAD_CELL);
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const list = ROAD_GRID.get(ix * 100000 + iz);
    if (!list) continue;
    for (const s of list) {
      if (s.r.highway && !withHighways) continue;
      const dx = s.bx - s.ax, dz = s.bz - s.az;
      const L2 = dx * dx + dz * dz || 1e-9;
      const t = Math.max(0, Math.min(1, ((x - s.ax) * dx + (z - s.az) * dz) / L2));
      const d = Math.hypot(s.ax + t * dx - x, s.az + t * dz - z);
      if (d > radius) continue;
      const prev = best.get(s.r.name);
      if (!prev || d < prev.dist) best.set(s.r.name, { road: s.r, dist: d, horizontal: Math.abs(dx) > Math.abs(dz) });
    }
  }
  return [...best.values()].sort((a, b) => a.dist - b.dist);
}

// The streets as a list for the map's search (one entry per name, with its extent)
const MAJOR_STREETS = new Set(['Bloor St W', 'Bloor St E', 'College St', 'Carlton St', 'Dundas St W', 'Dundas St E', 'Queen St W', 'Queen St E',
  'King St W', 'King St E', 'Front St W', 'Front St E', 'Lake Shore Blvd W', 'Lake Shore Blvd E', 'Queens Quay W', 'Queens Quay E',
  'Yonge St', 'Bay St', 'University Ave', 'Spadina Ave', 'Bathurst St', 'Jarvis St', 'Church St', 'Parliament St', 'Sherbourne St',
  'Gerrard St E', 'Wellesley St E', 'Wellesley St W', 'Richmond St W', 'Adelaide St W', 'Adelaide St E', 'Richmond St E', 'Avenue Rd',
  'Harbord St', 'Queen\'s Park', 'Queen\'s Park Cres W', 'Queen\'s Park Cres E', 'Bremner Blvd', 'Simcoe St', 'York St', 'John St']);
const ALL_STREETS = (() => {
  const byName = new Map();
  for (const r of ROADS) {
    if (r.highway) continue;
    if (!byName.has(r.name)) byName.set(r.name, []);
    byName.get(r.name).push(r);
  }
  const out = [];
  for (const [name, rs] of byName) {
    let n = 0, sx = 0, sz = 0, x0 = Infinity, x1 = -Infinity, z0 = Infinity, z1 = -Infinity, len = 0;
    for (const r of rs) {
      for (let i = 0; i < r.pts.length; i++) {
        const p = r.pts[i];
        n++; sx += p.x; sz += p.z;
        x0 = Math.min(x0, p.x); x1 = Math.max(x1, p.x); z0 = Math.min(z0, p.z); z1 = Math.max(z1, p.z);
        if (i) len += Math.hypot(p.x - r.pts[i - 1].x, p.z - r.pts[i - 1].z);
      }
    }
    out.push({ name, short: name, full: rs[0].full, x: sx / n, z: sz / n, minX: x0, maxX: x1, minZ: z0, maxZ: z1, length: len,
      isMajor: MAJOR_STREETS.has(name), horizontal: x1 - x0 > z1 - z0, roads: rs });
  }
  return out.sort((a, b) => b.length - a.length);
})();

// The expressways: the Gardiner on its piers above Lake Shore Blvd and the Don Valley Parkway (one polyline per
// carriageway), their ramps, and the rail & streetcar lines
const EXPRESSWAYS = GEO.expressways.map((e) => ({ name: e.name, lanes: e.lanes, w: e.w, pts: toPts(e.pts) }));
const RAMPS = GEO.ramps.map((r) => ({ ...r, pts: toPts(r.pts) }));
const RAILS = GEO.rails.map(([kind, service, name, bridge, flat]) => ({ kind, service, name, bridge: !!bridge, pts: toPts(flat) }));

// ---------------------------------------------------------------------------------------------------------------------
// Blocks: every real curb island (raised sidewalk slab) with its lot rectangles inside the property line
//   poly: curb outline [{x, z}], rects: [[x0, x1, z0, z1], ...] building lots (axis-aligned), hints: per lot
//   [tallest, mean, built share] of the real buildings standing on it (OpenStreetMap heights), park / rail / parking:
//   share covered by parkland, railway land & surface car parks, parkName, rect: the island is an axis-aligned
//   rectangle, frames: irregular islands' lots laid out along the streets they front, [[θ, px, pz, rects], ...] (rects in
//   a frame turned by θ about (px, pz): world = p + R_y(θ)·(local − p)) with frameHints alike, or null
// ---------------------------------------------------------------------------------------------------------------------
const BLOCKS = GEO.blocks.map(([flat, rects, park, parkName, isRect, frames, rail, parking, hints, frameHints], id) => {
  const poly = toPts(flat);
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity, a = 0, cx = 0, cz = 0;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const p = poly[i], q = poly[j];
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
    const c = q.x * p.z - p.x * q.z;
    a += c; cx += (q.x + p.x) * c; cz += (q.z + p.z) * c;
  }
  a *= 0.5;
  const area = Math.abs(a);
  return {
    id, poly, rects, frames: frames || null, park, parkName, rect: !!isRect, area,
    rail: rail || 0, parking: parking || 0, hints: hints || [], frameHints: frameHints || null,
    minX, maxX, minZ, maxZ,
    cx: a ? cx / (6 * a) : (minX + maxX) / 2,
    cz: a ? cz / (6 * a) : (minZ + maxZ) / 2,
    median: Math.min(maxX - minX, maxZ - minZ) < 9 && !(park > 0.6)
  };
});
// Spatial index of the blocks (64 m cells)
const BLOCK_CELL = 64;
const BLOCK_GRID = new Map();
for (const b of BLOCKS) {
  for (let ix = Math.floor(b.minX / BLOCK_CELL); ix <= Math.floor(b.maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(b.minZ / BLOCK_CELL); iz <= Math.floor(b.maxZ / BLOCK_CELL); iz++) {
      const k = ix * 100000 + iz;
      if (!BLOCK_GRID.has(k)) BLOCK_GRID.set(k, []);
      BLOCK_GRID.get(k).push(b);
    }
  }
}
function pointInPoly(poly, x, z) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i], b = poly[j];
    if ((a.z > z) !== (b.z > z) && x < ((b.x - a.x) * (z - a.z)) / (b.z - a.z) + a.x) inside = !inside;
  }
  return inside;
}
/** The block (curb island) under (x, z), or null on the roadway / in the water */
function blockAt(x, z) {
  const list = BLOCK_GRID.get(Math.floor(x / BLOCK_CELL) * 100000 + Math.floor(z / BLOCK_CELL));
  if (!list) return null;
  for (const b of list) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (b.rect || pointInPoly(b.poly, x, z)) return b;
  }
  return null;
}
/** Blocks whose bounds overlap a rectangle */
function blocksInRect(minX, maxX, minZ, maxZ) {
  const out = new Set();
  for (let ix = Math.floor(minX / BLOCK_CELL); ix <= Math.floor(maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(minZ / BLOCK_CELL); iz <= Math.floor(maxZ / BLOCK_CELL); iz++) {
      const list = BLOCK_GRID.get(ix * 100000 + iz);
      if (list) for (const b of list) if (b.maxX > minX && b.minX < maxX && b.maxZ > minZ && b.minZ < maxZ) out.add(b);
    }
  }
  return [...out];
}

// The real buildings' heights over downtown on a 4 m grid (tools/geo-extra.mjs): 0 where no building stands
const HEIGHT_GRID = (() => {
  const g = GEO.heightGrid;
  if (!g) return null;
  const bin = atob(g.rle);
  const cells = new Uint8Array(g.w * g.h);
  for (let i = 0, k = 0; i + 1 < bin.length; i += 2) {
    const v = bin.charCodeAt(i);
    const n = bin.charCodeAt(i + 1);
    cells.fill(v, k, k + n);
    k += n;
  }
  return { ...g, cells };
})();
/** Height (m) of the real building standing at (x, z) (OpenStreetMap), 0 where there is none, null outside downtown */
function realHeightAt(x, z) {
  const g = HEIGHT_GRID;
  if (!g) return null;
  const i = Math.floor((x - g.x0) / g.cell);
  const j = Math.floor((z - g.z0) / g.cell);
  if (i < 0 || j < 0 || i >= g.w || j >= g.h) return null;
  return g.cells[j * g.w + i] * g.step;
}

// Parks, lawns & playfields, open water inside downtown (ponds, fountains, the Don), and the real towers of 40 m and up
const PARKS = GEO.parks.map((p) => ({ name: p.name, cat: p.cat, area: p.area, rings: p.rings.map(toPts) }));
const WATER_BODIES = GEO.water.map((w) => ({ name: w.name, kind: w.kind, ring: toPts(w.ring) }));
const TOWERS = GEO.towers.map((t) => {
  const ring = toPts(t.ring);
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (const p of ring) {
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
  }
  return { ...t, ring, minX, maxX, minZ, maxZ, cx: (minX + maxX) / 2, cz: (minZ + maxZ) / 2 };
});
const PIERS = GEO.piers.map((p) => (p.ring ? { ...p, ring: toPts(p.ring) } : { ...p, line: toPts(p.line) }));
const RUNWAYS = GEO.runways.map((r) => ({ ...r, pts: toPts(r.pts) }));
// Street furniture from OpenStreetMap: traffic signals, TTC entrances & stops, Canada Post boxes, hydrants, trees...
const FURNITURE = {
  ...Object.fromEntries(['signals', 'crossings', 'postBoxes', 'hydrants', 'trees', 'lamps', 'bikeShare', 'benches', 'bins']
    .map((k) => [k, toPts(GEO.furniture[k] || [])])),
  subway: (GEO.furniture.subway || []).map(([x, z, name]) => ({ x, z, name })),
  stops: (GEO.furniture.stops || []).map(([x, z, streetcar, name]) => ({ x, z, streetcar: !!streetcar, name })),
  ferry: (GEO.furniture.ferry || []).map(([x, z, name]) => ({ x, z, name }))
};

// ---------------------------------------------------------------------------------------------------------------------
// Neighbourhoods (by real street positions) for building profiles, labels & the maps
// ---------------------------------------------------------------------------------------------------------------------
const NEIGHBOURHOOD_NAMES = {
  financial: 'Financial District', south_core: 'South Core', entertainment: 'Entertainment District', king_west: 'King West',
  fort_york: 'Fort York', cityplace: 'CityPlace', harbourfront: 'Harbourfront', queen_west: 'Queen West', alexandra_park: 'Alexandra Park',
  kensington: 'Kensington Market', chinatown: 'Chinatown', grange_park: 'Grange Park', discovery: 'Discovery District',
  yonge_dundas: 'Downtown Yonge', st_lawrence: 'St. Lawrence', old_town: 'Old Town', distillery: 'Distillery District',
  west_don_lands: 'West Don Lands', corktown: 'Corktown', moss_park: 'Moss Park', regent_park: 'Regent Park',
  cabbagetown: 'Cabbagetown', st_james_town: 'St. James Town', church_wellesley: 'Church-Wellesley Village', bay_street: 'Bay Street Corridor',
  yorkville: 'Yorkville', queens_park: 'Queen\'s Park', uoft: 'University of Toronto', harbord: 'Harbord Village', annex: 'The Annex',
  garden_district: 'Garden District', east_bayfront: 'East Bayfront'
};
function districtAt(x, z) {
  if (z > 1000) return x > 600 ? 'east_bayfront' : 'harbourfront';
  if (z > 650) {
    // south of Front St: the railway lands & the towers of the South Core, CityPlace and the St. Lawrence neighbourhood
    if (x < -1600) return 'fort_york';
    if (x < -620) return 'cityplace';
    if (x < 320) return 'south_core';
    if (x < 1300) return 'st_lawrence';
    if (x < 1720) return 'distillery';
    return 'west_don_lands';
  }
  if (z > 100) {
    // Queen St to Front St
    if (x < -1450) return 'king_west';
    if (x < -620) return 'entertainment';
    if (x < 120) return 'financial';
    if (x < 820) return 'old_town';
    if (x < 1300) return 'st_lawrence';
    if (x < 1720) return 'corktown';
    return 'west_don_lands';
  }
  if (z > -460) {
    // Dundas St to Queen St
    if (x < -1640) return 'queen_west';
    if (x < -1150) return x > -1450 ? 'chinatown' : 'alexandra_park';
    if (x < -620) return 'grange_park';
    if (x < -150) return 'discovery';
    if (x < 300) return 'yonge_dundas';
    if (x < 1260) return 'moss_park';
    if (x < 1940) return 'regent_park';
    return 'corktown';
  }
  if (z > -1040) {
    // College St to Dundas St
    if (x < -1700) return 'kensington';
    if (x < -1150) return x < -1500 ? 'kensington' : 'chinatown';
    if (x < -620) return 'grange_park';
    if (x < -150) return 'discovery';
    if (x < 300) return 'yonge_dundas';
    if (x < 1260) return 'garden_district';
    if (x < 1940) return 'regent_park';
    return 'cabbagetown';
  }
  if (z > -1800) {
    // Bloor St to College St
    if (x < -1680) return 'harbord';
    if (x < -1150) return 'uoft';
    if (x < -380) return 'queens_park';
    if (x < 0) return 'bay_street';
    if (x < 820) return 'church_wellesley';
    if (x < 1260) return 'st_james_town';
    return 'cabbagetown';
  }
  // Bloor St and north of it
  if (x < -1150) return 'annex';
  if (x < 380) return 'yorkville';
  if (x < 1260) return 'st_james_town';
  return 'cabbagetown';
}
for (const b of BLOCKS) b.district = districtAt(b.cx, b.cz);

// ---------------------------------------------------------------------------------------------------------------------
// Landmarks (real footprints from OpenStreetMap: centre, grid-aligned width x depth, height, outline)
// ---------------------------------------------------------------------------------------------------------------------
const LANDMARK_SITES = Object.fromEntries(Object.entries(GEO.landmarks).map(([k, l]) => [k, { ...l, ring: toPts(l.ring) }]));
const site = (name, fallback) => LANDMARK_SITES[name] || fallback;
const LANDMARKS = [
  ['cntower', 'CN Tower', 'CN Tower', 'CN Tower', 'Entertainment District'],
  ['rogers', 'Rogers Centre', 'Rogers Centre', 'Rogers Centre', 'Entertainment District'],
  ['union', 'Union Station', 'Union Station', 'Union Station', 'Financial District'],
  ['royalyork', 'Fairmont Royal York', 'Royal York', 'Fairmont Royal York Hotel', 'Financial District'],
  ['fcp', 'First Canadian Place', 'First Canadian Pl', 'First Canadian Place', 'Financial District'],
  ['scotia', 'Scotia Plaza', 'Scotia Plaza', 'Scotia Plaza', 'Financial District'],
  ['rbc', 'Royal Bank Plaza', 'Royal Bank Plaza', 'Royal Bank Plaza South Tower', 'Financial District'],
  ['brookfield', 'Brookfield Place & Allen Lambert Galleria', 'Brookfield Place', 'Brookfield Place', 'Financial District'],
  ['cityhall', 'City Hall & Nathan Phillips Square', 'City Hall', 'Toronto City Hall', 'Downtown Yonge'],
  ['oldcityhall', 'Old City Hall', 'Old City Hall', 'Old City Hall', 'Downtown Yonge'],
  ['eaton', 'CF Toronto Eaton Centre', 'Eaton Centre', 'CF Toronto Eaton Centre', 'Downtown Yonge'],
  ['arena', 'Scotiabank Arena', 'Scotiabank Arena', 'Scotiabank Arena', 'South Core'],
  ['flatiron', 'Gooderham (Flatiron) Building', 'Gooderham Bldg', 'Gooderham Building', 'St. Lawrence'],
  ['market', 'St. Lawrence Market', 'St. Lawrence Mkt', 'St. Lawrence Market South', 'St. Lawrence'],
  ['legislature', 'Ontario Legislative Building', 'Queen\'s Park', 'Ontario Legislative Building', 'Queen\'s Park'],
  ['rom', 'Royal Ontario Museum', 'ROM', 'Royal Ontario Museum', 'Yorkville'],
  ['ago', 'Art Gallery of Ontario', 'AGO', 'Art Gallery of Ontario', 'Grange Park'],
  ['roythomson', 'Roy Thomson Hall', 'Roy Thomson Hall', 'Roy Thomson Hall', 'Entertainment District'],
  ['ripleys', 'Ripley\'s Aquarium of Canada', 'Ripley\'s Aquarium', 'Ripley\'s Aquarium of Canada', 'Entertainment District'],
  ['massey', 'Massey Hall', 'Massey Hall', 'Massey Hall', 'Downtown Yonge']
].map(([id, name, short, osm, district]) => {
  const s = site(osm, null);
  return s ? { id, name, short, x: s.x, z: s.z, district } : null;
}).filter(Boolean);
LANDMARKS.push(
  { id: 'dundassq', name: 'Sankofa Square (Yonge-Dundas)', short: 'Sankofa Square', x: POINTS.dundasSquare.x + 25, z: POINTS.dundasSquare.z + 30, district: 'Downtown Yonge' },
  { id: 'distillery', name: 'Distillery District', short: 'Distillery', x: POINTS.distillery.x, z: POINTS.distillery.z, district: 'Distillery District' },
  { id: 'kensington', name: 'Kensington Market', short: 'Kensington', x: POINTS.kensington.x, z: POINTS.kensington.z, district: 'Kensington Market' },
  { id: 'ferry', name: 'Jack Layton Ferry Terminal', short: 'Ferry Terminal', x: POINTS.ferryTerminal.x, z: POINTS.ferryTerminal.z, district: 'Harbourfront' },
  { id: 'harbourfront', name: 'Harbourfront Centre', short: 'Harbourfront', x: POINTS.harbourfront.x, z: POINTS.harbourfront.z, district: 'Harbourfront' }
);

/** The nearest point of a named street's centreline to (nearX, nearZ) */
function roadPoint(street, nearX, nearZ) {
  {
    // the nearest point of a named street's centreline to (nearX, nearZ), 3.6 m to the right of it
    let best = null;
    for (const r of ROADS) {
      if (r.name !== street) continue;
      for (let i = 0; i + 1 < r.pts.length; i++) {
        const a = r.pts[i], b = r.pts[i + 1];
        const dx = b.x - a.x, dz = b.z - a.z;
        const L2 = dx * dx + dz * dz || 1;
        const t = Math.max(0, Math.min(1, ((nearX - a.x) * dx + (nearZ - a.z) * dz) / L2));
        const x = a.x + dx * t, z = a.z + dz * t;
        const d = Math.hypot(x - nearX, z - nearZ);
        if (!best || d < best.d) best = { d, x, z };
      }
    }
    return best ? { x: best.x, z: best.z } : { x: nearX, z: nearZ };
  }
}
// Where the players start: southbound on Yonge St between Queen St & King St (heading 0 faces south)
const SPAWN = (() => {
  const p = roadPoint('Yonge St', 10, 200);
  return { x: p.x, z: p.z };
})();

// Street-level arrivals shared by every travel mode. Heading 0 faces south (+z, towards the lake), PI north.
const TELEPORT_LOCATIONS = (() => {
  const at = (p, dx, dz, heading) => ({ x: p.x + dx, z: p.z + dz, heading });
  const P = POINTS;
  const bremner = roadPoint('Bremner Blvd', P.cnTower.x + 30, P.cnTower.z + 60);
  const front = roadPoint('Front St W', P.unionStation.x, P.unionStation.z);
  const queen = roadPoint('Queen St W', P.nathanPhillips.x + 30, P.nathanPhillips.z);
  const yonge = roadPoint('Yonge St', P.dundasSquare.x, P.dundasSquare.z + 60);
  const front2 = roadPoint('Front St E', P.stLawrenceMarket.x, P.stLawrenceMarket.z);
  const qp = roadPoint('Queen\'s Park', P.queensPark.x, P.queensPark.z + 120);
  const qq = roadPoint('Queens Quay W', P.harbourfront.x, P.harbourfront.z);
  const mill = roadPoint('Mill St', P.distillery.x, P.distillery.z);
  return {
    cntower: at(bremner, 0, 3.6, Math.atan2(P.cnTower.x - bremner.x, P.cnTower.z - (bremner.z + 3.6))),
    union: at(front, 0, -3.6, Math.PI * 0.5),
    cityhall: at(queen, 0, 3.6, -Math.PI * 0.5),
    dundas: at(yonge, 3.6, 0, 0),
    stlawrence: at(front2, 0, 3.6, -Math.PI * 0.5),
    queenspark: at(qp, 3.6, 0, Math.PI),
    harbourfront: at(qq, 0, 3.6, -Math.PI * 0.5),
    distillery: at(mill, 0, 1.4, -Math.PI * 0.5) // (Mill St is a narrow street)
  };
})();

/**
 * Exact street / landmark name at any world (x, z): the nearest roads of the real street centreline
 */
function getLocationLabel(x, z) {
  for (const lm of LANDMARKS) {
    if (Math.hypot(x - lm.x, z - lm.z) < 80) {
      const near = nearestRoads(x, z, 120);
      const ns = near.find((r) => !r.horizontal);
      const ew = near.find((r) => r.horizontal);
      return `${lm.name}${ns && ew ? ` · ${ns.road.name} & ${ew.road.name}` : ''}`;
    }
  }
  const near = nearestRoads(x, z, 160);
  const ns = near.find((r) => !r.horizontal);
  const ew = near.find((r) => r.horizontal);
  if (!isOnLand(x, z, -2)) {
    if (z > 1000) return x < -1500 ? 'Toronto Harbour · Western Gap' : 'Toronto Harbour';
    return 'Lake Ontario';
  }
  if (waterDistance(x, z) < 30 && z > 900) return `Harbourfront${ew ? ` · near ${ew.road.name}` : ''}`;
  if (ns && ew) return `${ns.road.name} & ${ew.road.name}`;
  if (near.length) return near[0].road.name;
  return NEIGHBOURHOOD_NAMES[districtAt(x, z)] || 'Downtown Toronto';
}

// Keyboard shortcuts are ignored while typing into a form field (e.g. the map's street search box)
function isTypingInField(e) {
  return e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
}

// Traffic signal cycle shared by the signal heads (street-details.js) and the traffic (traffic.js), in seconds: the
// major road green until majorAmber, amber until majorRed; the cross road green from majorRed until minorAmber, amber
// until the end of the cycle. Pedestrians cross with the traffic that runs parallel to them, stepping off only on the
// WALK, the first `walk` seconds of its green: long enough before the cross traffic's green for the slowest walker to
// get across the widest road.
const SIGNAL_TIMING = { cycle: 60, avenueAmber: 26, avenueRed: 30, streetAmber: 56, walk: 7 };

// 'green', 'amber' or 'red' for the major road (group 0) or the cross road at a given time
function signalPhase(time, isAvenue) {
  const { cycle, avenueAmber, avenueRed, streetAmber } = SIGNAL_TIMING;
  const t = ((time % cycle) + cycle) % cycle;
  if (isAvenue) return t < avenueAmber ? 'green' : t < avenueRed ? 'amber' : 'red';
  return t < avenueRed ? 'red' : t < streetAmber ? 'green' : 'amber';
}

// Do pedestrians walking alongside the major road (or the cross road) have the WALK at a given time?
function walkSignal(time, isAvenue) {
  const { cycle, avenueRed, walk } = SIGNAL_TIMING;
  const t = (((time - (isAvenue ? 0 : avenueRed)) % cycle) + cycle) % cycle;
  return t < walk;
}

